  "options_you_can_choose": [
    "Modify to a nonstop Atlanta (ATL) → Los Angeles (LAX) on the same day (allowed change).",
    "Assess eligibility to cancel and then book Atlanta (ATL) → Las Vegas (LAS) on the same day (only if cancellation rules are met)."
  ],
  "what_i_need_from_you": {
    "required_for_any_change": [
      "Your user ID",
      "Your reservation ID"
    ],
    "to_check_date_and_availability": [
      "Confirm the exact date of your return flight (or I can read it from your reservation once you provide the IDs)."
    ],
    "if_you_want_to_pursue_cancel_and_rebook_to_LAS": [
      "Reason for cancellation (e.g., change of plan, airline cancelled, health/weather with insurance).",
      "Whether the booking was made within the last 24 hours, or if the return is a business fare, or if you have travel insurance that covers the reason."
    ]
  },
  "notes_on_pricing": "For allowed flight changes (keeping origin/destination/trip type), I will show the new itinerary price and any fare difference before you confirm. If we cancel and rebook, eligibility must be verified first; refunds go back to the original payment methods when applicable.",
